package es.idynamicsax.ostris.service;
import es.idynamicsax.ostris.core.ProtocolException; import java.math.BigInteger; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class JournalProjectionService {private final JdbcTemplate jdbc;public JournalProjectionService(JdbcTemplate j){jdbc=j;}
 @Transactional(readOnly=true) public Map<UUID,BigInteger> reconstruct(UUID tenantId,UUID communityId,UUID unitId){Map<UUID,BigInteger> result=new LinkedHashMap<>();jdbc.query("select e.account_id,sum(e.amount) from ostris.journal_entry e join ostris.journal_transaction t on t.id=e.transaction_id where e.tenant_id=? and e.community_id=? and t.unit_id=? group by e.account_id order by e.account_id",rs->{result.put(rs.getObject(1,UUID.class),rs.getBigDecimal(2).toBigIntegerExact());},tenantId,communityId,unitId);return Map.copyOf(result);}
 @Transactional(readOnly=true) public void verifyProjection(UUID tenantId,UUID communityId,UUID unitId){Map<UUID,BigInteger> truth=reconstruct(tenantId,communityId,unitId);jdbc.query("select id,balance_projection from ostris.account where tenant_id=? and community_id=? and unit_id=?",rs->{UUID id=rs.getObject(1,UUID.class);BigInteger projected=rs.getBigDecimal(2).toBigIntegerExact();if(!projected.equals(truth.getOrDefault(id,BigInteger.ZERO)))throw new ProtocolException("PROJECTION_DRIFT","Balance projection differs from journal for "+id);},tenantId,communityId,unitId);}
}
